   "num": 4,
   "section": "A.1",
   "text": "Why can you get an RF burn from an antenna even before touching it?",
   "options": [
    "Antennas get hot from sunlight",
    "Static from the feeder",
    "Lightning",
    "An electrical arc can form between the skin and a conductor at high RF voltage"
   ],
